import { expect, test } from '../fixtures';

/** A secret the flow was driven with. Set it in the environment or in sova/.env. */
function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) throw new Error(`${name} is not set. Add it to sova/.env or the environment.`);
  return value;
}

// Starts signed out, whatever session the rest of the suite shares.
test.use({ storageState: { cookies: [], origins: [] } });

test('Sign in bob', async ({ page }) => {
  await test.step('Open /auth/login', async () => {
    await page.goto('/auth/login');
  });

  await test.step('Type the bob username', async () => {
    await page.getByRole('textbox', { name: 'Username or Email address', exact: true }).fill(env('APP_BOB_USER'));
  });

  await test.step('Type the bob password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill(env('APP_BOB_PASSWORD'));
  });

  await test.step('Press Login', async () => {
    await page.getByRole('button', { name: 'Login', exact: true }).click();
  });

  await test.step('Open the settings page, only for signed-in users', async () => {
    await page.goto('/user/settings/general');
  });

  await test.step('The account settings page is shown to the signed-in user', async () => {
    await expect(page.getByRole('listitem', { name: 'Account Settings', exact: true }).or(page.getByRole('listitem').filter({ hasText: /^Account Settings$/ }))).toBeVisible();
  });

  await test.step('Keep the signed-in session for the other tests', async () => {
    await page.context().storageState({ path: process.env.SOVA_AUTH_STATE_BOB!, indexedDB: true });
  });
});
